    void purr() const { cout << "输出 " << times << " 下" << endl; }
};

class Knead : virtual public MeowCat {
public:
    Knead(int k) : MeowCat(k) { cout << "搭会踩初始化值的那一半" << endl; }
    void knead() const { cout << "踩初始化值 " << times << " 下" << endl; }
};

int main() {
    int n = 0;
    cin >> n;

    return 0;
}

